'use client'

import { useState } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "../ui/card"
import { Badge } from "../ui/badge"
import { Button } from "../ui/button"
import { ReminderCard } from "./ReminderCard"
import { useReminders } from "../../hooks/useReminders"
import { Reminder } from "../../lib/types"
import { RefreshCw, Filter, Search } from "lucide-react"

export function RemindersList() {
  const { data: reminders, isLoading, error, refetch } = useReminders()
  const [filter, setFilter] = useState<'all' | 'active' | 'sent' | 'overdue'>('all')
  const [searchTerm, setSearchTerm] = useState('')

  const filterReminders = (reminders: Reminder[]) => {
    let filtered = reminders

    // Apply status filter
    if (filter === 'active') {
      filtered = filtered.filter(r => r.status?.toLowerCase() === 'active' || r.status?.toLowerCase() === 'pending')
    } else if (filter === 'sent') {
      filtered = filtered.filter(r => r.status?.toLowerCase() === 'sent')
    } else if (filter === 'overdue') {
      filtered = filtered.filter(r => {
        if (r.status?.toLowerCase() === 'sent') return false
        try {
          const [day, month, year] = r.date.split('/').map(Number)
          const [hours, minutes] = r.time.split(':').map(Number)
          const targetDate = new Date(year, month - 1, day, hours, minutes)
          return new Date() > targetDate
        } catch {
          return false
        }
      })
    }

    // Apply search filter
    if (searchTerm) {
      filtered = filtered.filter(r =>
        r.message.toLowerCase().includes(searchTerm.toLowerCase()) ||
        r.targetGroup?.toLowerCase().includes(searchTerm.toLowerCase())
      )
    }

    return filtered
  }

  const filteredReminders = reminders ? filterReminders(reminders) : []

  const getFilterCount = (filterType: typeof filter) => {
    if (!reminders) return 0
    return filterReminders(reminders.filter(() => true)).length
  }

  if (error) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="text-center">
            <p className="text-destructive mb-4">Error loading reminders: {error.message}</p>
            <Button onClick={() => refetch()} variant="outline">
              <RefreshCw className="h-4 w-4 mr-2" />
              Try Again
            </Button>
          </div>
        </CardContent>
      </Card>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header and Controls */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle>Reminders</CardTitle>
            <Button
              onClick={() => refetch()}
              variant="outline"
              size="sm"
              disabled={isLoading}
            >
              {isLoading ? (
                <RefreshCw className="h-4 w-4 animate-spin" />
              ) : (
                <RefreshCw className="h-4 w-4" />
              )}
              Refresh
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          {/* Search Bar */}
          <div className="flex items-center space-x-2 mb-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <input
                type="text"
                placeholder="Search reminders..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10 pr-4 py-2 border border-input rounded-md w-full bg-background"
              />
            </div>
          </div>

          {/* Filter Buttons */}
          <div className="flex flex-wrap gap-2">
            {(['all', 'active', 'sent', 'overdue'] as const).map((filterType) => (
              <Button
                key={filterType}
                variant={filter === filterType ? 'default' : 'outline'}
                size="sm"
                onClick={() => setFilter(filterType)}
                className="capitalize"
              >
                {filterType}
                <Badge variant="secondary" className="ml-2">
                  {filterType === 'all' ? reminders?.length || 0 : getFilterCount(filterType)}
                </Badge>
              </Button>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Reminders Grid */}
      {isLoading ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {[...Array(6)].map((_, i) => (
            <Card key={i} className="animate-pulse">
              <CardHeader>
                <div className="h-4 bg-gray-200 rounded w-3/4"></div>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  <div className="h-3 bg-gray-200 rounded w-1/2"></div>
                  <div className="h-3 bg-gray-200 rounded w-1/4"></div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      ) : filteredReminders.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredReminders.map((reminder, index) => (
            <ReminderCard key={`${reminder.rowIndex}-${index}`} reminder={reminder} />
          ))}
        </div>
      ) : (
        <Card>
          <CardContent className="p-6">
            <div className="text-center text-muted-foreground">
              {searchTerm ? (
                <p>No reminders found matching "{searchTerm}"</p>
              ) : (
                <p>No {filter === 'all' ? '' : filter} reminders found</p>
              )}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}